function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "any_failed";\nINSERT OR IGNORE INTO "any_failed" ("status") SELECT json_extract(b0."col1", '$.args[0]') FROM "outcome_a" b0 WHERE json_extract(b0."col1", '$.fn') = 'error';\nINSERT OR IGNORE INTO "any_failed" ("status") SELECT json_extract(b0."col1", '$.args[0]') FROM "outcome_b" b0 WHERE json_extract(b0."col1", '$.fn') = 'error';\nDELETE FROM "both_ok";\nINSERT OR IGNORE INTO "both_ok" ("body_a", "body_b") SELECT json_extract(b0."col1", '$.args[0]'), json_extract(b1."col1", '$.args[0]') FROM "outcome_a" b0, "outcome_b" b1 WHERE json_extract(b0."col1", '$.fn') = 'ok' AND json_extract(b1."col1", '$.fn') = 'ok'`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const any_failed = multisetDiff(before.any_failed, after.any_failed);
  const both_ok = multisetDiff(before.both_ok, after.both_ok);
  const outcome_a = multisetDiff(before.outcome_a, after.outcome_a);
  const outcome_b = multisetDiff(before.outcome_b, after.outcome_b);
  return {
    rels: [
      { rel: "any_failed", add: any_failed.add, del: any_failed.del },
      { rel: "both_ok", add: both_ok.add, del: both_ok.del },
      { rel: "outcome_a", add: outcome_a.add, del: outcome_a.del },
      { rel: "outcome_b", add: outcome_b.add, del: outcome_b.del },
    ],
    carryPending: false,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // fork_join_error_arm_is_a_value: no edge rules -- absorb arrivals, recompute levels, diff.
}

const INCREMENTAL_PROGRAM_SAFE = true;
const RECONCILE_EVERY_TICK = false;
const EMITTER_MODE = process.env.SPREFA_TSV2_EMITTER_MODE === "naive" ? "naive" : "incremental";

function runIncrementalTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return IncrementalRuntime.prepareTick(seam, INCREMENTAL_RELATIONS).pipe(
    concatMap(() => IncrementalRuntime.applyArrivals(seam, arrivals, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyLevelsBeforeEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyEdges(seam, INCREMENTAL_EDGE_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => of(undefined)),
    concatMap(() => of(undefined)),
    concatMap(() => IncrementalRuntime.recomputeLevelsAfterEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS, RECONCILE_EVERY_TICK)),
    concatMap(() => IncrementalRuntime.readBoundary(seam, INCREMENTAL_RELATIONS)),
    concatMap((rels) => IncrementalRuntime.promoteFrontiers(seam, INCREMENTAL_RELATIONS).pipe(
      map((carryPending): ITickDeltas => ({ rels, carryPending })),
    )),
  );
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  if (EMITTER_MODE === "naive" || !INCREMENTAL_PROGRAM_SAFE) {
    return runNaiveTick(seam, arrivals);
  }
  return runIncrementalTick(seam, arrivals);
}

